public class Main {public static void main(String[]a)throws InterruptedException{Thread worker=new Thread(()->{System.out.println("Worker running: "+Thread.currentThread().getName());try{Thread.sleep(100);}catch(InterruptedException e){Thread.currentThread().interrupt();}});System.out.println("Before start: "+worker.getState());worker.start();System.out.println("After start: "+worker.getState());worker.join();System.out.println("After join: "+worker.getState());}}
